step "Copy the 'anon public' key (under Legacy API keys, starts eyJ…)"
step "or the 'Publishable key' (starts sb_publishable_…). Either works."
note "Never the service_role or secret key: those bypass all security."
while :; do
  ask SHEET_ANON_KEY "Paste the anon or publishable key:"
  [[ "$SHEET_ANON_KEY" =~ ^(eyJ|sb_publishable_) ]] && break
  warn "That doesn't look like an anon (eyJ…) or publishable (sb_publishable_…) key."
done
write_env SHEET_ANON_KEY "$SHEET_ANON_KEY"
